$conn = New-Object System.Data.SqlClient.SqlConnection("Server=localhost\SQLEXPRESS;Database=GR_EMA_DISTRIBUTION;Integrated Security=True;TrustServerCertificate=True"); $conn.Open(); $cmd = $conn.CreateCommand(); $cmd.CommandText = "SELECT YEAR(MV_PointDate) as Y, MONTH(MV_PointDate) as M, COUNT(*) FROM RT_MOUVEMENT WHERE MV_Point = 1 AND MV_PointDate IS NOT NULL GROUP BY YEAR(MV_PointDate), MONTH(MV_PointDate) ORDER BY Y, M"; $reader = $cmd.ExecuteReader(); while ($reader.Read()) { Write-Host "$($reader.GetValue(0))-$($reader.GetValue(1)): $($reader.GetValue(2)) lignes" } $conn.Close()
